/**
 * Question generator that creates multiple choice questions dynamically
 * from the rich AWL dataset according to the stage/sublist requested.
 */
export function generateQuestionsForStage(stageId: number, count: number = 8): Question[] {
  // Find words for this stage, or fallback to all words
  const stageWords = AWL_WORDS_DATA.filter((w) => w.sublist === stageId);
  const wordsPool = stageWords.length >= 4 ? stageWords : AWL_WORDS_DATA;
  const allWords = AWL_WORDS_DATA;

  // Shuffle wordsPool
  const shuffled = [...wordsPool].sort(() => 0.5 - Math.random());
  const selectedWords = shuffled.slice(0, Math.min(count, shuffled.length));

  return selectedWords.map((word, index) => {
    // Alternate question types
    const questionTypes: ('meaning' | 'fill_blank' | 'synonym' | 'collocation')[] = [
      'fill_blank',
      'meaning',
      'collocation',
      'synonym',
    ];
    const type = questionTypes[index % questionTypes.length];

    // Pick 3 random distractor words (prefer same stage/sublist for focused review)
    const poolDistractors = wordsPool.filter((w) => w.id !== word.id);
    const distractors = (poolDistractors.length >= 3 ? poolDistractors : allWords.filter((w) => w.id !== word.id))
      .sort(() => 0.5 - Math.random())
      .slice(0, 3);

    let content = '';
    let correctAnswer = '';
    let options: string[] = [];
    let explanation = '';

    if (type === 'fill_blank') {
      // Replace word in example sentence with blank
      const regex = new RegExp(`\\b${word.word}\\b`, 'i');
      if (regex.test(word.example)) {
        content = `Điền từ học thuật thích hợp vào chỗ trống:\n"${word.example.replace(regex, '_______')}"`;
      } else {
        content = `Điền từ thích hợp: "... [${word.meaningVi}] ..."\n"${word.example.replace(new RegExp(word.word.slice(0, 4), 'i'), '_______')}"`;
      }
      correctAnswer = word.word;
      options = [correctAnswer, ...distractors.map((d) => d.word)].sort(() => 0.5 - Math.random());
      explanation = `Từ đúng là "${word.word}" (${word.pos}): ${word.meaningVi}. Ví dụ: ${word.example}`;
    } else if (type === 'meaning') {
      content = `Nghĩa tiếng Việt chuẩn xác nhất của từ học thuật "${word.word}" (${word.phonetic}) là gì?`;
      correctAnswer = word.meaningVi;
      options = [correctAnswer, ...distractors.map((d) => d.meaningVi)].sort(() => 0.5 - Math.random());
      explanation = `"${word.word}" có nghĩa là: ${word.meaningVi}. Định nghĩa tiếng Anh: ${word.definitionEn}`;
    } else if (type === 'collocation') {
      const topCollocation = word.collocations[0] || `${word.word} research`;
      content = `Cụm từ kết hợp học thuật (Academic Collocation) nào phổ biến nhất với "${word.word}"?`;
      correctAnswer = topCollocation;
      // create plausible false collocations using distractor words
      options = [
        correctAnswer,
        distractors[0].collocations[0] || `${distractors[0].word} system`,
        distractors[1].collocations[0] || `${distractors[1].word} study`,
        distractors[2].collocations[0] || `${distractors[2].word} approach`,
      ].sort(() => 0.5 - Math.random());
      explanation = `Cụm từ kết hợp chuẩn: "${topCollocation}". Các collocations khác gồm: ${word.collocations.join(', ')}.`;
    } else {
      // synonym or antonym question
      const relations = getWordLexicalRelations(word.word);
      const isSynonym = index % 2 === 0;
      if (isSynonym && relations.synonyms && relations.synonyms.length > 0) {
        content = `Từ nào sau đây là TỪ ĐỒNG NGHĨA (Synonym) gần nhất với từ học thuật "${word.word}" (${word.pos})?`;
        correctAnswer = relations.synonyms[0];
        const wrongPool = [
          relations.antonyms[0] || distractors[0].word,
          distractors[1].word,
          distractors[2].word,
        ].filter((w) => w && w.toLowerCase() !== correctAnswer.toLowerCase());
        options = [correctAnswer, ...wrongPool.slice(0, 3)].sort(() => 0.5 - Math.random());
        explanation = `Từ đồng nghĩa chính xác của "${word.word}" (${word.meaningVi}) là "${correctAnswer}".\n• Các từ đồng nghĩa khác: ${relations.synonyms.join(', ')}.\n• Các từ trái nghĩa: ${relations.antonyms.join(', ')}.`;
      } else if (relations.antonyms && relations.antonyms.length > 0) {
        content = `Từ nào sau đây là TỪ TRÁI NGHĨA (Antonym) đối lập nghĩa nhất với từ học thuật "${word.word}" (${word.pos})?`;
        correctAnswer = relations.antonyms[0];
        const wrongPool = [
          relations.synonyms[0] || distractors[0].word,
          distractors[1].word,
          distractors[2].word,
        ].filter((w) => w && w.toLowerCase() !== correctAnswer.toLowerCase());
        options = [correctAnswer, ...wrongPool.slice(0, 3)].sort(() => 0.5 - Math.random());
        explanation = `Từ trái nghĩa đối lập của "${word.word}" (${word.meaningVi}) là "${correctAnswer}".\n• Các từ trái nghĩa khác: ${relations.antonyms.join(', ')}.\n• Các từ đồng nghĩa: ${relations.synonyms.join(', ')}.`;
      } else {
        content = `Từ/dạng từ nào sau đây cùng họ từ (Word Family) hoặc gắn liền với "${word.word}"?`;
        correctAnswer = word.wordFamily[0] || word.word;
        options = [
          correctAnswer,
          distractors[0].wordFamily[0] || distractors[0].word,
          distractors[1].wordFamily[0] || distractors[1].word,
          distractors[2].wordFamily[0] || distractors[2].word,
        ].sort(() => 0.5 - Math.random());
        explanation = `Họ từ của "${word.word}" gồm: ${[word.word, ...word.wordFamily].join(', ')}.`;
      }
    }

    return {
      id: `q_${stageId}_${word.id}_${index}`,
      subjectId: stageId,
      content,
      type,
      options,
      correctAnswer,
      explanation,
      difficulty: word.difficulty,
      targetWord: word.word,
    };
  });
}
